   "page": "印 48",
   "q": "比較 $21x^2+x+1=3ax^2+(a+3b)x+(b+3)$ 的同次項係數。",
   "steps": [
    "$x^2$ 項：$3a=21$，所以 $a=7$",
    "常數項：$b+3=1$，所以 $b=-2$",
    "檢查 $x$ 項：$a+3b=7-6=1$，與左邊的 $x$ 係數相同",
    "驗算：$(7x-2)(3x+1)+3$",
    "$=21x^2+x-2+3=21x^2+x+1$"
   ],
